"""Report card assembly: health verdict, ranked action queue, run persistence.

The output boundary is deliberate.  This module emits a ranked list with
share counts and stops — it never places an order.  The failure mode of the
whole system is therefore a bad suggestion a human declines, not a bad fill.
"""

from __future__ import annotations

import json
import os
from datetime import datetime, timezone

from .adapter import Holding
from .portfolio import CONCENTRATION_LIMIT

DISCLAIMER = (
    "Educational and research use only. Generated by an AI system that can be "
    "wrong, including confidently wrong. Not investment advice and not a "
    "recommendation to buy, sell or hold any security. The author is not a "
    "SEBI-registered adviser. Verify independently and consult a registered "
    "adviser before acting."
)

#: Weight multiplier applied to a position for each action.
_TARGET_MULTIPLIER = {
    "exit": 0.0,
    "trim": 0.5,
    "hold": 1.0,
    "accumulate": 1.25,
    "buy": 1.5,
}

#: Order the action queue is sorted in — losses first, additions last.
_PRIORITY = {"exit": 0, "trim": 1, "buy": 2, "accumulate": 3, "hold": 4}


def health_verdict(book: dict) -> dict:
    """One card: Healthy / Needs attention / High risk, plus why."""
    reasons: list[str] = []
    severe = 0

    conc = book["concentration"]
    if conc["top_sector_weight"] > 0.40:
        severe += 1
        reasons.append(
            f"{conc['top_sector']} is {conc['top_sector_weight'] * 100:.0f}% of the book"
        )
    elif conc["top_sector_breach"]:
        reasons.append(
            f"{conc['top_sector']} exceeds the {CONCENTRATION_LIMIT * 100:.0f}% sector limit"
        )
    if conc["top_name_breach"]:
        reasons.append(
            f"{conc['top_name']} alone is {conc['top_name_weight'] * 100:.0f}% of the book"
        )
    if conc["diversification_score"] < 30:
        severe += 1

    corr = book["correlation"]
    if corr["effective_bets"] < corr["nominal_holdings"] / 2:
        reasons.append(corr["headline"] + " — less diversified than it looks")

    risk = book["risk"]
    if risk["mismatch"]:
        severe += 1
        reasons.append(risk["mismatch"])

    bench = book["benchmark"]
    if bench["beating_index"] is False:
        reasons.append(
            f"lagging {bench['symbol']}: "
            f"{bench['portfolio_return_pct']}% vs {bench['benchmark_return_pct']}%"
        )

    if severe >= 2:
        status = "High risk"
    elif reasons:
        status = "Needs attention"
    else:
        status = "Healthy"

    return {"status": status, "reasons": reasons[:3], "all_reasons": reasons}


def action_queue(
    verdicts: dict[str, dict],
    holdings: list[Holding],
    book: dict,
) -> list[dict]:
    """Rank what to do first and translate it into share counts.

    Target weights are derived from each verdict's action, capped at the
    concentration limit, then renormalised.  The delta against the current
    weight becomes a concrete buy/sell quantity — "trim 34 HDFCBANK", not
    "consider reducing banking exposure".
    """
    weights = book["weights"]
    total_value = book["totals"]["market_value"]
    by_symbol = {h.symbol: h for h in holdings}

    # Targets are absolute, NOT renormalised to sum to 1.  Renormalising
    # would force every rupee freed by an exit straight back into whatever
    # remains — including positions the desk only mildly likes — turning
    # "sell three names" into "concentrate harder into the rest".  Anything
    # not allocated stays in cash, which is a legitimate destination.
    targets = {}
    for symbol, weight in weights.items():
        action = verdicts.get(symbol, {}).get("action", "hold")
        targets[symbol] = min(
            weight * _TARGET_MULTIPLIER.get(action, 1.0), CONCENTRATION_LIMIT
        )

    rows = []
    for symbol, target in targets.items():
        verdict = verdicts.get(symbol, {})
        action = verdict.get("action", "hold")
        price = verdict.get("last_close") or 0.0
        if not price:
            continue
        current_qty = by_symbol[symbol].qty
        target_qty = (target * total_value) / price
        delta = target_qty - current_qty
        # A hold is a hold.  Emitting "HOLD ... buy 5" is the kind of
        # self-contradiction that destroys trust in every other row.
        if action == "hold":
            delta = 0.0
        # Ignore sub-1% nudges elsewhere; churn is a cost, not a recommendation.
        elif abs(delta) * price < total_value * 0.01:
            delta = 0.0
        rows.append(
            {
                "symbol": symbol,
                "action": action,
                "engine": verdict.get("engine", "rules"),
                "current_weight_pct": round(weights[symbol] * 100, 2),
                "target_weight_pct": round(target * 100, 2),
                "shares_delta": int(delta) if abs(delta) >= 1 else 0,
                "side": "buy" if delta > 0 else ("sell" if delta < 0 else "none"),
                "price": price,
                "pnl_pct": verdict.get("pnl_pct"),
                "stop": verdict.get("stop"),
                "confidence": verdict.get("confidence"),
                "rationale": (verdict.get("reasons") or [""])[0],
                "backtest": (
                    verdict.get("backtest", {}).get("best_supported_setup") or "unsupported"
                ),
            }
        )

    cash_pct = max(0.0, 1.0 - sum(targets.values()))
    for row in rows:
        row["resulting_cash_pct"] = round(cash_pct * 100, 2)

    rows.sort(
        key=lambda r: (
            _PRIORITY.get(r["action"], 5),
            r["pnl_pct"] if r["pnl_pct"] is not None else 0,
        )
    )
    return rows


def render_markdown(book: dict, health: dict, queue: list[dict], dials: dict) -> str:
    """The human-facing report card."""
    t = book["totals"]
    bench, corr, conc, risk = book["benchmark"], book["correlation"], book["concentration"], book["risk"]
    engines = {r["engine"] for r in queue}
    badge = "🟢 AI-generated" if engines == {"llm"} else (
        "🟠 Rules-based fallback" if engines == {"rules"} else "🟡 Mixed (see per-row engine)"
    )

    lines = [
        "# Portfolio Report Card",
        "",
        f"**Verdict: {health['status']}** · {badge}",
        "",
        f"> Horizon `{dials['horizon']}` · Risk profile `{dials['risk_profile']}` "
        f"· Depth `{dials['depth']}`",
        "",
        "## The numbers",
        "",
        "| Metric | Value |",
        "| --- | --- |",
        f"| Market value | ₹{t['market_value']:,.0f} |",
        f"| Invested | ₹{t['invested']:,.0f} |",
        f"| P&L | ₹{t['pnl']:,.0f} ({t['return_pct']}%) |",
        f"| vs {bench['symbol']} | {bench['portfolio_return_pct']}% vs {bench['benchmark_return_pct']}% |",
        f"| Effective bets | {corr['headline']} |",
        f"| Diversification | {conc['diversification_score']}/100 |",
        f"| Risk level | {risk['level']} (beta {risk['beta_vs_benchmark']}) |",
        "",
    ]

    if health["reasons"]:
        lines += ["## Why", ""] + [f"- {r}" for r in health["reasons"]] + [""]

    lines += [
        "## Do this first",
        "",
        "| # | Action | Symbol | Shares | Weight → | P&L | Stop | Backtest | Engine |",
        "| --- | --- | --- | --- | --- | --- | --- | --- | --- |",
    ]
    rank = 0
    for row in queue:
        if row["action"] == "hold" and row["shares_delta"] == 0:
            continue
        rank += 1
        qty = abs(row["shares_delta"])
        move = f"{row['side']} {qty}" if qty else "—"
        pnl = f"{row['pnl_pct']:+.1f}%" if row["pnl_pct"] is not None else "—"
        lines.append(
            f"| {rank} | {row['action'].upper()} | {row['symbol']} | {move} | "
            f"{row['current_weight_pct']}% → {row['target_weight_pct']}% | {pnl} | "
            f"{row['stop'] or '—'} | {row['backtest']} | {row['engine']} |"
        )
    if rank == 0:
        lines.append("| — | HOLD | all positions | — | — | — | — | — | — |")

    holds = [r["symbol"] for r in queue if r["action"] == "hold" and r["shares_delta"] == 0]
    if holds:
        lines += ["", f"**Unchanged:** {', '.join(sorted(holds))}"]

    if corr["most_correlated_pairs"]:
        lines += ["", "## Pairs moving as one bet", "", "| Pair | Correlation |", "| --- | --- |"]
        for p in corr["most_correlated_pairs"]:
            lines.append(f"| {p['a']} / {p['b']} | {p['corr']} |")

    cash = queue[0].get("resulting_cash_pct") if queue else None
    if cash:
        lines += [
            "",
            f"**Resulting cash: {cash}%** — proceeds are not force-redeployed; "
            "cash is a position.",
        ]

    lines += ["", "---", "", f"_{DISCLAIMER}_", ""]
    return "\n".join(lines)


def _zone_cell(zone: dict) -> str:
    """Strong-zone cell: 'yes' or how far below the high it sits."""
    off = zone.get("pct_from_high")
    if zone.get("at_ath"):
        return "ATH"
    if zone.get("in_zone"):
        return "yes"
    return f"{off * 100:.0f}%" if off is not None else "?"


def render_bajaj_sections(analysis: dict) -> str:
    """Framework-specific detail appended to the report card.

    Separate from :func:`render_markdown` so the baseline report is not
    carrying gate tables that mean nothing to it.
    """
    ctx = analysis.get("market_context") or {}
    regime = ctx.get("regime") or {}
    ranks = ctx.get("sector_rankings") or {}
    verdicts = analysis.get("verdicts") or {}
    lines: list[str] = ["", "## Bajaj framework", ""]

    if regime:
        lines += [
            f"**Market regime: {regime.get('regime', '?').upper()}** · "
            f"deployment ceiling {int((regime.get('deployment_ceiling') or 0) * 100)}% "
            f"of planned capital per new position",
            "",
        ]
        lines += [f"- {r}" for r in regime.get("reasons", [])]
        breadth_note = (regime.get("breadth") or {}).get("caveat")
        if breadth_note:
            lines.append(f"- ⚠ {breadth_note}")
        lines.append("")

    ranked = ranks.get("ranked") or []
    if ranked:
        lines += [
            "### Sector ranking",
            "",
            "| # | Sector | Mean RS | Names | Leading |",
            "| --- | --- | --- | --- | --- |",
        ]
        for row in ranked:
            warn = " ⚠" if row.get("proxy_warning") else ""
            lines.append(
                f"| {row['rank']} | {row['sector']}{warn} | {row['mean_rs']:+.2f} | "
                f"{row['constituents']} | {'yes' if row['leading'] else 'no'} |"
            )
        lines += [
            "",
            "⚠ ranked on fewer than three holdings — that measures the stock, "
            "not the sector. Wire real sector indices in before gating on it.",
            "",
        ]

    gate_rows = [(s, v) for s, v in verdicts.items() if v.get("bajaj")]
    if gate_rows:
        lines += [
            "### Entry gates",
            "",
            "All six must pass independently — a strong business with dead "
            "momentum is a reject, not an average.",
            "",
            "| Symbol | Action | Fund /100 | Momentum | RS | Supertrend | Strong zone | Gates |",
            "| --- | --- | --- | --- | --- | --- | --- | --- |",
        ]
        for symbol, v in gate_rows:
            b = v["bajaj"]
            mom, ex = b["momentum"], b["exit_signal"]
            zone = (v.get("technical") or {}).get("strong_zone") or {}
            checks = b["entry_checklist"]["checks"]
            passed = sum(1 for c in checks if c["pass"])
            lines.append(
                f"| {symbol} | {v['action'].upper()} | {b['fundamental']['score']} | "
                f"{mom['zone']} | {mom['rs']:+.2f} | "
                f"{'red' if ex['supertrend_red'] else 'green'} | "
                f"{_zone_cell(zone)} | "
                f"{passed}/{len(checks)} |"
            )
        lines.append("")

    exits = [
        (s, v) for s, v in gate_rows if v["bajaj"]["exit_signal"]["exit"]
    ]
    if exits:
        lines += ["### Exit triggers fired", ""]
        for symbol, v in exits:
            ex = v["bajaj"]["exit_signal"]
            lines.append(f"- **{symbol}** — {ex['rule']}: {'; '.join(ex['triggers'])}")
        lines += [
            "",
            "_Technical exits require BOTH signals negative. One alone is a hold — "
            "the tolerance for noise most investors break first._",
            "",
        ]

    construction = analysis.get("portfolio_construction")
    if construction:
        lines += [
            "### Portfolio construction",
            "",
            f"- {construction['holdings']} holdings; {construction['capital_band']} "
            f"calls for {construction['target_range'][0]}-{construction['target_range'][1]} "
            f"— {'ok' if construction['count_ok'] else 'OUT OF BAND'}",
            f"- Core allocation {construction['core_weight_pct']}% against a "
            f"{construction['core_target_pct'][0]:.0f}-{construction['core_target_pct'][1]:.0f}% "
            f"target — {'ok' if construction['core_ok'] else 'SHORT'}",
        ]
        if construction["core_symbols"]:
            lines.append(f"- Core names: {', '.join(construction['core_symbols'])}")
        else:
            lines.append(
                "- **No core names.** Nothing in the book is strong on both "
                "fundamentals and momentum."
            )
        lines.append("")

    return "\n".join(lines)


def write_run(root: str, payload: dict, markdown: str, stamp: str | None = None) -> str:
    """Persist one run to a timestamped folder and return its path.

    Runs are immutable and self-describing so last month's verdict can be
    reopened and honestly checked against what actually happened.
    """
    stamp = stamp or datetime.now(timezone.utc).strftime("%Y-%m-%dT%H-%M-%SZ")
    path = os.path.join(root, stamp)
    os.makedirs(path, exist_ok=True)
    with open(os.path.join(path, "analysis.json"), "w", encoding="utf-8") as fh:
        json.dump(payload, fh, indent=2, default=str)
        fh.write("\n")
    with open(os.path.join(path, "report-card.md"), "w", encoding="utf-8") as fh:
        fh.write(markdown)
    return path
